package org.jlinalg.cli;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class HomerGenomeDataTest {
    @TempDir Path root;
    @Test void unicodeReferenceAndSourceIdsAreAliasedWithoutChangingCoordinates()throws Exception{var o=HomerGenomeFixture.options(root);var d=HomerGenomeFixture.stage(o,root.resolve("work"));assertEquals(6,d.regions().size());assertEquals("p α",d.regions().get(0).sourceId());assertEquals("C000000001",d.regions().get(0).contig());assertEquals(1001,d.regions().get(0).original().start1());assertEquals("BGB000000001",d.regions().get(2).alias());assertTrue(Files.readString(root.resolve("work/reference.tsv")).contains("original header"));d.verify();}
    @Test void crlfAndCaseArePreservedThroughFormattingThenExplicitlyMasked()throws Exception{var o=HomerGenomeFixture.options(root);Path p=Path.of(o.get("genome"));Files.writeString(p,">chrα original\r\n"+"acGTACGTACGTACGT".repeat(1250)+"\r\n");o.put("mask-lowercase","yes");var d=HomerGenomeFixture.stage(o,root.resolve("work"));assertTrue(Files.readString(root.resolve("work/stage-genome.fa")).contains("acGT"));assertTrue(d.regions().get(0).dna().contains("NNGT"));assertFalse(Files.readString(root.resolve("work/stage-genome.fa")).contains("\r"));}
    @Test void numericSizeAndAsymmetricShiftKeepOriginalHalfBaseRules()throws Exception{var o=HomerGenomeFixture.options(root);o.put("size","-50,150");var d=HomerGenomeFixture.stage(o,root.resolve("work"));assertEquals(201,d.regions().get(0).dna().length());assertEquals(1010,d.regions().get(0).extraction().start1());assertEquals(1410,d.regions().get(1).extraction().start1());}
    @Test void numericOverlapUsesInclusiveCppIntegerCenteredWindows()throws Exception{var p=new org.jlinalg.sequence.HomerGenomicSequences.Interval(100,121,'+');assertArrayEquals(new long[]{10,210},HomerGenomeData.overlapSpan(p,200));var index=new HomerGenomeData.OverlapIndex(List.of(new long[]{10,210}));assertTrue(index.overlaps(new long[]{210,410}));assertFalse(index.overlaps(new long[]{211,411}));assertArrayEquals(new long[]{11,209},HomerGenomeData.overlapSpan(p,199));}
    @Test void removalExcludesBackgroundBeforeExtractionPopulation()throws Exception{var o=HomerGenomeFixture.options(root);Path p=Path.of(o.get("background"));Files.writeString(p,Files.readString(p)+"chrα\t1050\t1170\toverlap\t1\t+\n");o.put("background-overlap","remove-original");var d=HomerGenomeFixture.stage(o,root.resolve("work"));assertEquals("original-overlap-excluded",d.regions().get(6).disposition());assertFalse(d.regions().get(6).sequenceRetained());}
    @Test void duplicatedSourceIdsRequireOrdinalPermission()throws Exception{var o=HomerGenomeFixture.options(root);Path p=Path.of(o.get("peaks"));Files.writeString(p,Files.readString(p).replace("minus","p α"));assertThrows(IOException.class,()->HomerGenomeFixture.stage(o,root.resolve("bad")));o.put("duplicate-ids","retain-ordinal");var d=HomerGenomeFixture.stage(o,root.resolve("good"));assertEquals(1,d.duplicates());assertNotEquals(d.regions().get(0).alias(),d.regions().get(1).alias());}
    @Test void unknownStrandsAreNeverInferredWithoutPolicy()throws Exception{var o=HomerGenomeFixture.options(root);Path p=Path.of(o.get("peaks"));Files.writeString(p,Files.readString(p).replace("\t+\n","\t.\n"));assertThrows(IOException.class,()->HomerGenomeFixture.stage(o,root.resolve("bad")));o.put("unknown-strand","original-plus");assertEquals('+',HomerGenomeFixture.stage(o,root.resolve("good")).regions().get(0).original().strand());}
    @Test void invalidContigAndBoundsFailBeforeOriginalLaunch()throws Exception{var o=HomerGenomeFixture.options(root);Path p=Path.of(o.get("peaks"));String original=Files.readString(p);for(String text:List.of(original.replace("chrα","chrX"),original.replace("1000\t1120","0\t25000"),original.replace("1000\t1120","1200\t1120"))){Files.writeString(p,text);assertThrows(Exception.class,()->HomerGenomeFixture.stage(o,root.resolve("bad"+Math.abs(text.hashCode()))));}}
    @Test void allSourceAndStagedHashesAreRechecked()throws Exception{var o=HomerGenomeFixture.options(root);var d=HomerGenomeFixture.stage(o,root.resolve("work"));Files.writeString(Path.of(o.get("genome")),"changed");assertThrows(IOException.class,d::verify);}
    @Test void operationAndInputCapacitiesFailBeforeAnalysis()throws Exception{var o=HomerGenomeFixture.options(root);o.put("maximum-operations","1");assertThrows(IOException.class,()->HomerGenomeFixture.stage(o,root.resolve("operations")));o.remove("maximum-operations");o.put("maximum-input-bytes","100");assertThrows(IOException.class,()->HomerGenomeFixture.stage(o,root.resolve("bytes")));}
    @Test void noncanonicalLettersRequireExplicitAlphabetPolicy()throws Exception{var o=HomerGenomeFixture.options(root);Path p=Path.of(o.get("genome"));Files.writeString(p,Files.readString(p).replace("ACGTACGTACGTACGT","RCGTACGTACGTACGT"));assertThrows(IOException.class,()->HomerGenomeFixture.stage(o,root.resolve("bad")));o.put("alphabet","mask-n");var d=HomerGenomeFixture.stage(o,root.resolve("good"));assertTrue(d.regions().get(0).dna().contains("N"));}
    @Test void gzipReferenceIsDecodedWithCaseAndRawBytesRetained()throws Exception{var o=HomerGenomeFixture.options(root);Path original=Path.of(o.get("genome")),gzip=root.resolve("reference.gz");try(var out=new java.util.zip.GZIPOutputStream(Files.newOutputStream(gzip))){out.write(Files.readAllBytes(original));}o.put("genome",gzip.toString());var d=HomerGenomeFixture.stage(o,root.resolve("work"));assertEquals(6,d.regions().size());assertArrayEquals(Files.readAllBytes(gzip),Files.readAllBytes(root.resolve("work/input-genome")));}
    @Test void noCanonicalDiscoveryWindowsFailBeforeLaunchingOriginal()throws Exception{var o=HomerGenomeFixture.options(root);Path p=Path.of(o.get("genome"));Files.writeString(p,">chrα\n"+"NCGT".repeat(5000)+"\n");assertThrows(IOException.class,()->HomerGenomeFixture.stage(o,root.resolve("bad")));}

    @Test void knownOnlyRetainsNonseedableSequencesAndDoesNotApplyDiscoveryLimits()throws Exception{var o=HomerGenomeFixture.options(root);o.put("analysis","known");for(String key:new String[]{"comparison-motifs","motif-length","mismatches","motifs-to-find"})o.remove(key);o.put("maximum-neighborhoods","1");Files.writeString(Path.of(o.get("genome")),">chrα\n"+"NCGT".repeat(5000)+"\n");var d=HomerGenomeFixture.stage(o,root.resolve("work"));assertEquals(6,d.regions().stream().filter(HomerGenomeData.Region::analytic).count());assertEquals(1,d.known().size());assertTrue(d.comparison().isEmpty());assertFalse(Files.exists(root.resolve("work/discovery-input.tsv")));assertFalse(Files.exists(root.resolve("work/stage-comparison.motif")));d.verify();}
    @Test void denovoOnlyStagesComparisonModelsWithoutClaimingKnownEnrichment()throws Exception{var o=HomerGenomeFixture.options(root);o.put("analysis","denovo");o.remove("known-motifs");var d=HomerGenomeFixture.stage(o,root.resolve("work"));assertTrue(d.known().isEmpty());assertEquals(1,d.comparison().size());assertFalse(Files.exists(root.resolve("work/input-known-motifs")));assertFalse(Files.exists(root.resolve("work/known-models.tsv")));assertTrue(Files.exists(root.resolve("work/discovery-input.tsv")));d.verify();}
    @Test void knownOnlyStillBoundsItsActualFixedModelAuditWork()throws Exception{var o=HomerGenomeFixture.options(root);o.put("analysis","known");for(String key:new String[]{"comparison-motifs","motif-length","mismatches","motifs-to-find"})o.remove(key);o.put("maximum-operations","1");assertThrows(IOException.class,()->HomerGenomeFixture.stage(o,root.resolve("work")));}

}
